async def run_rag_benchmark():
    print("=" * 80)
    print("EDUPATH AI — RAG 50-QUESTION BENCHMARK & EVALUATION SUITE")
    print("=" * 80)
    print(f"Timestamp: {datetime.utcnow().isoformat()}Z")
    print(f"Total Benchmark Queries: {len(RAG_BENCHMARK_50_QUESTIONS)}")
    print(f"Evaluator: RAGService Hybrid Dense + Lexical + RRF Reranker")
    print("-" * 80)

    async with AsyncSessionLocal() as session:
        # 1. Setup Benchmark Test User
        test_email = f"benchmark_rag_{uuid.uuid4().hex[:6]}@edupath.internal"
        test_user = User(
            id=str(uuid.uuid4()),
            email=test_email,
            full_name="RAG Benchmark Evaluator",
            hashed_password=get_password_hash("BenchmarkSecret123!")
        )
        session.add(test_user)
        await session.flush()
        print(f"[1/4] Created benchmark evaluator user: {test_user.id}")

        # 2. Index Benchmark Knowledge Base
        total_chunks = 0
        all_created_chunks = []
        for doc_def in BENCHMARK_KNOWLEDGE_BASE:
            doc = Document(
                id=str(uuid.uuid4()),
                user_id=test_user.id,
                title=doc_def["title"],
                file_name=f"{doc_def['domain'].lower()}_reference.txt",
                file_path=f"uploads/{doc_def['domain'].lower()}_reference.txt",
                file_size=sum(len(c) for c in doc_def["chunks"]),
                file_type="txt",
                status="ready",
                chunk_count=len(doc_def["chunks"])
            )
            session.add(doc)
            await session.flush()

            for idx, chunk_text in enumerate(doc_def["chunks"]):
                chunk = DocumentChunk(
                    id=str(uuid.uuid4()),
                    document_id=doc.id,
                    chunk_index=idx,
                    content=chunk_text,
                    page_number=idx + 1
                )
                session.add(chunk)
                all_created_chunks.append(chunk)
                total_chunks += 1

        await session.commit()
        print(f"[2/4] Created {len(BENCHMARK_KNOWLEDGE_BASE)} documents with {total_chunks} text chunks.")

        # 3. Generate Vector Embeddings and Index via RAG Service
        print(f"[3/4] Generating embeddings and indexing chunks via RAGService...")
        await rag_service.index_chunks(session, all_created_chunks)
        print(f"      Successfully indexed {len(all_created_chunks)} document embeddings.")

        # 4. Execute 50-Question Retrieval Benchmark
        print(f"[4/4] Executing 50-Question Retrieval Evaluation Benchmark...")
        evaluation = await rag_service.evaluate_retrieval(
            session=session,
            user_id=test_user.id,
            test_queries=RAG_BENCHMARK_50_QUESTIONS
        )

        avg_precision = evaluation["average_precision_at_3"]
        mrr = evaluation["mean_reciprocal_rank_mrr"]
        details = evaluation["benchmark_details"]

        print("-" * 80)
        print("DOMAIN-BY-DOMAIN BENCHMARK BREAKDOWN:")
        print("-" * 80)

        domain_stats = {}
        for q, res in zip(RAG_BENCHMARK_50_QUESTIONS, details):
            d = q["domain"]
            domain_stats.setdefault(d, {"total": 0, "prec_sum": 0.0, "mrr_sum": 0.0, "perfect_hits": 0})
            domain_stats[d]["total"] += 1
            domain_stats[d]["prec_sum"] += res["precision_at_3"]
            domain_stats[d]["mrr_sum"] += res["reciprocal_rank"]
            if res["reciprocal_rank"] == 1.0:
                domain_stats[d]["perfect_hits"] += 1

        for dom, s in sorted(domain_stats.items()):
            n = s["total"]
            p = round(s["prec_sum"] / n, 3)
            m = round(s["mrr_sum"] / n, 3)
            perf = s["perfect_hits"]
            print(f"  * {dom:<25} | Queries: {n:>2} | Precision@3: {p:>5.3f} | MRR: {m:>5.3f} | Rank-1 Hits: {perf}/{n}")

        hit_1 = evaluation.get("hit_at_1_rate", 0.0)
        hit_3 = evaluation.get("hit_at_3_rate", 0.0)

        print("=" * 80)
        print("OVERALL RAG BENCHMARK EVALUATION RESULTS:")
        print(f"  * Total Queries Evaluated:    {evaluation['total_benchmark_queries']}")
        print(f"  * Mean Reciprocal Rank (MRR): {mrr:.3f} (Required: >= 0.750)")
        print(f"  * Hit@1 (Rank-1 Precision):   {hit_1:.3f} (Required: >= 0.800)")
        print(f"  * Hit@3 (Recall@3):           {hit_3:.3f} (Required: >= 0.900)")
        print(f"  * Average Precision@3:        {avg_precision:.3f}")
        print("=" * 80)

        # Assert criteria
        assert len(details) == 50, f"Expected 50 query results, got {len(details)}"
        assert mrr >= 0.75, f"MRR {mrr} below threshold 0.75"
        assert hit_1 >= 0.80, f"Hit@1 {hit_1} below threshold 0.80"
        assert hit_3 >= 0.90, f"Hit@3 {hit_3} below threshold 0.90"
        assert avg_precision >= 0.50, f"Precision@3 {avg_precision} below threshold 0.50"
        print("[SUCCESS] All 50 RAG Information Retrieval Benchmark criteria PASSED perfectly!")
        return evaluation

if __name__ == "__main__":
    asyncio.run(run_rag_benchmark())
